      const decodedLinkSegments = decodedMarkdownLink.split(/[\\/]/);
      let parentTraversalCount = 0;
      let currentDirSegmentCount = 0;
      let emptySegmentCount = 0;
      let meaningfulSegmentCount = 0;
      let encodedSegmentCount = 0;
      for (
        let segmentIndex = 0;
        segmentIndex < decodedLinkSegments.length;
        segmentIndex += 1
      ) {
        const decodedSegment = decodedLinkSegments[segmentIndex];
        if (decodedSegment === undefined) {
          emptySegmentCount += 1;
        } else if (decodedSegment === '..') {
          parentTraversalCount += 1;
        } else if (decodedSegment === '.') {
          currentDirSegmentCount += 1;
        } else if (decodedSegment === '') {
          emptySegmentCount += 1;
        } else {
          meaningfulSegmentCount += 1;
          if (decodedSegment.includes('%')) {
            encodedSegmentCount += 1;
          } else if (decodedSegment.includes(' ')) {
            meaningfulSegmentCount += 0;
          }
        }
      }

