      for (
        let sourceIndex = 0;
        sourceIndex < sourcesToTry.length;
        sourceIndex += 1
      ) {
        if (aliasedSourceMatch) {
          break;
        }
        const sourceRoot = sourcesToTry[sourceIndex];
        if (sourceRoot !== undefined) {
          let joinedSource: string;
          if (parentTraversalCount > 0) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else if (mdLink.startsWith('/')) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else if (emptySegmentCount > 0 && meaningfulSegmentCount === 0) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else if (currentDirSegmentCount > 0) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else if (encodedSegmentCount > 0) {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          } else {
            joinedSource = path.join(sourceRoot, decodedMarkdownLink);
          }

          const relativeToSite = path.relative(siteDir, joinedSource);
          const posixRelativeToSite = posixPath(relativeToSite);
          let normalizedRelative = posixRelativeToSite;
          if (normalizedRelative.startsWith('\\\\?\\')) {
