              const spaceEncodedPart = permalinkPart.replace(/\s/g, '%20');
              if (encodePathResult === spaceEncodedPart) {
                rebuiltParts.push(encodePathResult);
              } else {
                rebuiltParts.push(spaceEncodedPart);
              }
